import pandas as pd
import numpy as np

df = pd.read_csv('chunks_csv/outlierr/2022_transport.csv')
adj_df = pd.read_csv(ADJACENCY_PATH)

adj_dict = {b: set() for b in df['borough']}
for _, row in adj_df.iterrows():
    b, n = row['borough'], row['neighbor']
    if b in adj_dict and n in adj_dict:
        adj_dict[b].add(n)
        adj_dict[n].add(b)

val = dict(zip(df['borough'], df['Transport_value']))

def neighbor_avg(b, S):
    ns = adj_dict[b] & S
    if len(ns) == 0:
        return np.nan
    return np.mean([val[n] for n in ns])

def theil_sen_slope(x, y):
    n = len(x)
    slopes = []
    for i in range(n):
        for j in range(i+1, n):
            if x[j] != x[i]:
                slopes.append((y[j] - y[i]) / (x[j] - x[i]))
    if not slopes:
        return 0.0
    return np.median(slopes)

def fit_robust(x, y):
    slope = theil_sen_slope(x, y)
    intercept = np.median(y - slope * x)
    return slope, intercept

def mad(vals, constant=1.4826):
    med = np.median(vals)
    return constant * np.median(np.abs(vals - med))

def run_iterative(threshold):
    S = set(df['borough'])
    while True:
        x_vals = []
        y_vals = []
        b_names = []
        for b in sorted(S):
            x_vals.append(neighbor_avg(b, S))
            y_vals.append(val[b])
            b_names.append(b)
        x_vals = np.array(x_vals)
        y_vals = np.array(y_vals)
        b_names = np.array(b_names)
        slope, intercept = fit_robust(x_vals, y_vals)
        preds = slope * x_vals + intercept
        resids = y_vals - preds
        ss = mad(resids)
        if ss == 0:
            ss = 1e-9
        zs = resids / ss
        max_idx = np.argmax(np.abs(zs))
        max_b = b_names[max_idx]
        if np.abs(zs[max_idx]) > threshold:
            S.remove(max_b)
        else:
            final_slope, final_intercept, final_ss = slope, intercept, ss
            break
    all_zs = {}
    for b in df['borough']:
        xb = neighbor_avg(b, S)
        pred = final_slope * xb + final_intercept
        all_zs[b] = (val[b] - pred) / final_ss
    return S, final_slope, final_intercept, final_ss, all_zs

for th in [3.0, 2.5, 2.0]:
    S, slope, inter, ss, all_zs = run_iterative(th)
    print(f'threshold={th}, retained={len(S)}, Wandsworth z={all_zs["Wandsworth"]:.5f}')
